[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Leap Studio — Your Reinvention and Experience Partner</title>
<meta name="description" content="A global creative agency that challenges the status quo to create transformative experiences that win hearts and move markets in the eco-digital era.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
<style>
/* ========== DESIGN SYSTEM ========== */
:root {
  --bg: #0A0A0A;
  --bg-elevated: #111111;
  --bg-card: #161616;
  --bg-card-hover: #1C1C1C;
  --border: rgba(255,255,255,0.08);
  --border-hover: rgba(255,255,255,0.16);
  --text-primary: #FFFFFF;
  --text-secondary: #A0A0A0;
  --text-muted: #666666;
  --accent-blue: #3B82F6;
  --accent-blue-hover: #2563EB;
  --accent-amber: #F59E0B;
  --accent-amber-hover: #D97706;
  --accent-blue-glow: rgba(59,130,246,0.15);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --max-width: 1280px;
  --nav-height: 72px;
}

/* ========== RESET ========== */
*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }
img { display: block; max-width: 100%; }
ul, ol { list-style: none; }

/* ========== UTILITIES ========== */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
@media (min-width: 768px) { .container { padding: 0 40px; } }
@media (min-width: 1024px) { .container { padding: 0 64px; } }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

/* ========== SKIP LINK ========== */
.skip-link {
  position: absolute; top: -100%; left: 16px; z-index: 10000;
  background: var(--accent-blue); color: #fff; padding: 12px 24px; border-radius: var(--radius-sm);
  font-weight: 600; transition: top var(--transition-fast);
}
.skip-link:focus { top: 16px; }

/* ========== NAVIGATION ========== */
.nav {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  height: var(--nav-height);
  background: rgba(10,10,10,0.85);
  backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--border);
  transition: background var(--transition-base);
}
.nav-inner {
  max-width: var(--max-width); margin: 0 auto; height: 100%;
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 24px;
}
@media (min-width: 768px) { .nav-inner { padding: 0 40px; } }
@media (min-width: 1024px) { .nav-inner { padding: 0 64px; } }
.nav-logo {
  font-size: 20px; font-weight: 700; letter-spacing: -0.02em;
  display: flex; align-items: center; gap: 8px;
}
.nav-logo-icon {
  width: 28px; height: 28px; background: var(--accent-blue);
  border-radius: var(--radius-sm); display: flex; align-items: center; justify-content: center;
  font-size: 14px; font-weight: 800;
}
.nav-links {
  display: none; align-items: center; gap: 32px;
}
@media (min-width: 1024px) { .nav-links { display: flex; } }
.nav-links a {
  font-size: 14px; font-weight: 500; color: var(--text-secondary);
  transition: color var(--transition-fast); position: relative;
}
.nav-links a:hover, .nav-links a:focus-visible { color: var(--text-primary); }
.nav-links a:focus-visible { outline: 2px solid var(--accent-blue); outline-offset: 4px; border-radius: 2px; }
.nav-right { display: flex; align-items: center; gap: 16px; }

/* Language Selector */
.lang-selector { position: relative; }
.lang-btn {
  display: flex; align-items: center; gap: 6px;
  font-size: 13px; font-weight: 500; color: var(--text-secondary);
  padding: 8px 12px; border-radius: var(--radius-sm);
  border: 1px solid var(--border); transition: all var(--transition-fast);
}
.lang-btn:hover, .lang-btn:focus-visible { color: var(--text-primary); border-color: var(--border-hover); }
.lang-btn:focus-visible { outline: 2px solid var(--accent-blue); outline-offset: 2px; }
.lang-btn svg { width: 14px; height: 14px; transition: transform var(--transition-fast); }
.lang-btn[aria-expanded="true"] svg { transform: rotate(180deg); }
.lang-dropdown {
  position: absolute; top: calc(100% + 8px); right: 0;
  min-width: 180px; background: var(--bg-card);
  border: 1px solid var(--border); border-radius: var(--radius-md);
  padding: 6px; opacity: 0; visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--transition-fast);
  box-shadow: 0 16px 48px rgba(0,0,0,0.4);
}
.lang-dropdown.active { opacity: 1; visibility: visible; transform: translateY(0); }
.lang-dropdown a {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 14px; border-radius: var(--radius-sm);
  font-size: 14px; color: var(--text-secondary);
  transition: all var(--transition-fast);
}
.lang-dropdown a:hover, .lang-dropdown a:focus-visible { background: rgba(255,255,255,0.06); color: var(--text-primary); }
.lang-dropdown a.active { color: var(--accent-blue); }
.lang-dropdown a .lang-code { font-weight: 600; color: var(--text-muted); margin-left: auto; font-size: 12px; }

/* Mobile menu toggle */
.nav-menu-btn {
  display: flex; align-items: center; justify-content: center;
  width: 44px; height: 44px; border-radius: var(--radius-sm);
  transition: background var(--transition-fast);
}
@media (min-width: 1024px) { .nav-menu-btn { display: none; } }
.nav-menu-btn:hover { background: rgba(255,255,255,0.06); }
.nav-menu-btn svg { width: 22px; height: 22px; }

/* Mobile Menu */
.mobile-menu {
  position: fixed; top: var(--nav-height); left: 0; right: 0; bottom: 0;
  background: var(--bg); z-index: 999;
  padding: 32px 24px; opacity: 0; visibility: hidden;
  transition: all var(--transition-base);
  overflow-y: auto;
}
.mobile-menu.active { opacity: 1; visibility: visible; }
.mobile-menu a {
  display: block; padding: 16px 0; font-size: 18px; font-weight: 500;
  color: var(--text-secondary); border-bottom: 1px solid var(--border);
  transition: color var(--transition-fast);
}
.mobile-menu a:hover { color: var(--text-primary); }

/* ========== HERO ========== */
.hero {
  position: relative; padding-top: calc(var(--nav-height) + 60px);
  padding-bottom: 80px; overflow: hidden; min-height: 85vh;
  display: flex; align-items: center;
}
@media (min-width: 768px) { .hero { padding-top: calc(var(--nav-height) + 80px); padding-bottom: 100px; min-height: 90vh; } }
.hero-bg {
  position: absolute; inset: 0; z-index: 0;
  background: radial-gradient(ellipse 80% 60% at 50% 40%, var(--accent-blue-glow), transparent);
  opacity: 0.6;
}
.hero-container { position: relative; z-index: 1; width: 100%; }
.hero-carousel { position: relative; }
.hero-slide {
  display: none; flex-direction: column; gap: 32px;
  animation: heroFadeIn 0.5s ease forwards;
}
.hero-slide.active { display: flex; }
@keyframes heroFadeIn {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}
.hero-tag {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 12px; font-weight: 600; text-transform: uppercase;
  letter-spacing: 0.08em; color: var(--accent-blue);
  padding: 6px 14px; background: rgba(59,130,246,0.1);
  border: 1px solid rgba(59,130,246,0.2); border-radius: 100px;
  width: fit-content;
}
.hero-tag svg { width: 14px; height: 14px; }
.hero-title {
  font-size: clamp(32px, 5vw, 64px); font-weight: 700;
  line-height: 1.1; letter-spacing: -0.03em; max-width: 800px;
}
.hero-description {
  font-size: clamp(16px, 2vw, 20px); color: var(--text-secondary);
  line-height: 1.6; max-width: 560px;
}
.hero-cta {
  display: inline-flex; align-items: center; gap: 10px;
  padding: 14px 28px; background: var(--accent-blue);
  color: #fff; font-size: 15px; font-weight: 600;
  border-radius: var(--radius-sm); width: fit-content;
  transition: all var(--transition-fast);
}
.hero-cta:hover { background: var(--accent-blue-hover); transform: translateY(-1px); }
.hero-cta:focus-visible { outline: 2px solid var(--accent-blue); outline-offset: 4px; }
.hero-cta svg { width: 16px; height: 16px; transition: transform var(--transition-fast); }
.hero-cta:hover svg { transform: translateX(3px); }

/* Hero navigation */
.hero-nav {
  display: flex; align-items: center; gap: 16px; margin-top: 48px;
}
.hero-dots { display: flex; gap: 8px; }
.hero-dot {
  width: 10px; height: 10px; border-radius: 50%;
  background: var(--text-muted); transition: all var(--transition-base);
  border: none; cursor: pointer;
}
.hero-dot.active { background: var(--accent-blue); width: 32px; border-radius: 5px; }
.hero-dot:focus-visible { outline: 2px solid var(--accent-blue); outline-offset: 2px; }
.hero-arrows { display: flex; gap: 8px; margin-left: auto; }
.hero-arrow {
  width: 44px; height: 44px; border-radius: 50%;
  border: 1px solid var(--border); display: flex;
  align-items: center; justify-content: center;
  transition: all var(--transition-fast);
}
.hero-arrow:hover { border-color: var(--border-hover); background: rgba(255,255,255,0.04); }
.hero-arrow:focus-visible { outline: 2px solid var(--accent-blue); outline-offset: 2px; }
.hero-arrow svg { width: 18px; height: 18px; }

/* ========== TEAM SECTION ========== */
.team-section {
  padding: 100px 0; position: relative;
  border-top: 1px solid var(--border);
}
@media (min-width: 768px) { .team-section { padding: 140px 0; } }
.section-label {
  font-size: 12px; font-weight: 600; text-transform: uppercase;
  letter-spacing: 0.1em; color: var(--accent-blue); margin-bottom: 16px;
}
.section-title {
  font-size: clamp(28px, 4vw, 48px); font-weight: 700;
  line-height: 1.15; letter-spacing: -0.02em; margin-bottom: 16px;
}
.section-subtitle {
  font-size: clamp(16px, 1.8vw, 18px); color: var(--text-secondary);
  line-height: 1.6; max-width: 600px;
}

/* Region Tabs */
.region-tabs {
  display: flex; gap: 4px; margin: 40px 0 32px;
  border-bottom: 1px solid var(--border); overflow-x: auto;
  -webkit-overflow-scrolling: touch; scrollbar-width: none;
}
.region-tabs::-webkit-scrollbar { display: none; }
.region-tab {
  padding: 12px 20px; font-size: 14px; font-weight: 500;
  color: var(--text-muted); white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
  margin-bottom: -1px;
}
.region-tab:hover { color: var(--text-secondary); }
.region-tab.active { color: var(--text-primary); border-bottom-color: var(--accent-blue); }
.region-tab:focus-visible { outline: 2px solid var(--accent-blue); outline-offset: 2px; border-radius: 2px; }

/* Team Carousel */
.team-carousel-wrapper { position: relative; }
.team-carousel {
  display: flex; gap: 24px; overflow-x: auto;
  scroll-snap-type: x mandatory; -webkit-overflow-scrolling: touch;
  scrollbar-width: none; padding-bottom: 8px;
}
.team-carousel::-webkit-scrollbar { display: none; }
.team-card {
  flex: 0 0 320px; scroll-snap-align: start;
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
  transition: all var(--transition-base);
}
@media (min-width: 768px) { .team-card { flex: 0 0 360px; } }
.team-card:hover { border-color: var(--border-hover); background: var(--bg-card-hover); }
.team-card-photo {
  width: 100%; height: 240px; object-fit: cover;
  background: linear-gradient(135deg, #1a1a2e, #16213e);
  display: flex; align-items: center; justify-content: center;
  position: relative; overflow: hidden;
}
.team-card-photo::after {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(to bottom, transparent 60%, var(--bg-card));
}
.team-card-initials {
  font-size: 48px; font-weight: 700; color: rgba(255,255,255,0.12);
  position: relative; z-index: 1;
}
.team-card-content { padding: 24px; }
.team-card-name { font-size: 18px; font-weight: 600; margin-bottom: 4px; }
.team-card-title { font-size: 14px; color: var(--accent-blue); margin-bottom: 16px; }
.team-card-quote {
  font-size: 14px; color: var(--text-secondary); line-height: 1.6;
  font-style: italic; margin-bottom: 20px;
  display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical;
  overflow: hidden;
}
.team-card-office {
  font-size: 13px; color: var(--text-muted); display: flex;
  align-items: center; gap: 6px;
}
.team-card-office svg { width: 14px; height: 14px; }
.team-card-cta {
  display: inline-flex; align-items: center; gap: 6px;
  margin-top: 16px; font-size: 13px; font-weight: 600;
  color: var(--accent-blue); transition: gap var(--transition-fast);
}
.team-card-cta:hover { gap: 10px; }
.team-card-cta svg { width: 14px; height: 14px; }

/* Carousel Nav Arrows */
.carousel-nav {
  display: flex; gap: 8px; margin-top: 24px;
  justify-content: flex-end;
}
.carousel-arrow {
  width: 44px; height: 44px; border-radius: 50%;
  border: 1px solid var(--border); display: flex;
  align-items: center; justify-content: center;
  transition: all var(--transition-fast);
}
.carousel-arrow:hover { border-color: var(--border-hover); background: rgba(255,255,255,0.04); }
.carousel-arrow:focus-visible { outline: 2px solid var(--accent-blue); outline-offset: 2px; }
.carousel-arrow svg { width: 16px; height: 16px; }

/* ========== WORK SHOWCASE ========== */
.work-section {
  padding: 100px 0; border-top: 1px solid var(--border);
}
@media (min-width: 768px) { .work-section { padding: 140px 0; } }
.work-carousel {
  display: flex; gap: 24px; overflow-x: auto;
  scroll-snap-type: x mandatory; -webkit-overflow-scrolling: touch;
  scrollbar-width: none; padding: 4px 0 16px;
}
.work-carousel::-webkit-scrollbar { display: none; }
.work-card {
  flex: 0 0 340px; scroll-snap-align: start;
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
  transition: all var(--transition-base); cursor: pointer;
}
@media (min-width: 768px) { .work-card { flex: 0 0 400px; } }
.work-card:hover { border-color: var(--border-hover); transform: translateY(-4px); }
.work-card-image {
  width: 100%; height: 220px; object-fit: cover;
  background: linear-gradient(135deg, #1a1a2e, #0f3460);
  position: relative;
}
.work-card-client {
  position: absolute; bottom: 16px; left: 16px;
  font-size: 11px; font-weight: 600; text-transform: uppercase;
  letter-spacing: 0.08em; color: var(--accent-amber);
  background: rgba(0,0,0,0.6); backdrop-filter: blur(8px);
  padding: 4px 10px; border-radius: 100px;
}
.work-card-body { padding: 24px; }
.work-card-title { font-size: 18px; font-weight: 600; margin-bottom: 12px; line-height: 1.3; }
.work-card-quote {
  font-size: 13px; color: var(--text-secondary); line-height: 1.6;
  font-style: italic; display: -webkit-box; -webkit-line-clamp: 3;
  -webkit-box-orient: vertical; overflow: hidden;
}
.work-card-quote-author { font-style: normal; color: var(--text-muted); margin-top: 8px; font-size: 12px; }
.work-card-link {
  display: inline-flex; align-items: center; gap: 6px;
  margin-top: 16px; font-size: 13px; font-weight: 600;
  color: var(--accent-blue); transition: gap var(--transition-fast);
}
.work-card-link:hover { gap: 10px; }
.work-card-link svg { width: 14px; height: 14px; }

/* ========== CTA BANNER ========== */
.cta-banner {
  padding: 100px 0; border-top: 1px solid var(--border);
}
@media (min-width: 768px) { .cta-banner { padding: 140px 0; } }
.cta-banner-inner {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-xl); padding: 64px 40px;
  text-align: center; position: relative; overflow: hidden;
}
@media (min-width: 768px) { .cta-banner-inner { padding: 80px 64px; } }
.cta-banner-glow {
  position: absolute; top: -50%; left: 50%; transform: translateX(-50%);
  width: 600px; height: 300px;
  background: radial-gradient(ellipse, var(--accent-blue-glow), transparent 70%);
  pointer-events: none;
}
.cta-banner-title {
  font-size: clamp(28px, 4vw, 44px); font-weight: 700;
  line-height: 1.15; letter-spacing: -0.02em;
  margin-bottom: 16px; position: relative;
}
.cta-banner-text {
  font-size: 17px; color: var(--text-secondary); line-height: 1.6;
  max-width: 540px; margin: 0 auto 32px; position: relative;
}
.cta-banner-btn {
  display: inline-flex; align-items: center; gap: 10px;
  padding: 16px 32px; background: var(--accent-blue);
  color: #fff; font-size: 15px; font-weight: 600;
  border-radius: var(--radius-sm); position: relative;
  transition: all var(--transition-fast);
}
.cta-banner-btn:hover { background: var(--accent-blue-hover); transform: translateY(-1px); }
.cta-banner-btn:focus-visible { outline: 2px solid var(--accent-blue); outline-offset: 4px; }
.cta-banner-btn svg { width: 16px; height: 16px; }

/* ========== HOW WE WORK ========== */
.how-section {
  padding: 100px 0; border-top: 1px solid var(--border);
}
@media (min-width: 768px) { .how-section { padding: 140px 0; } }
.how-grid {
  display: grid; grid-template-columns: 1fr; gap: 48px;
  margin-top: 48px; align-items: center;
}
@media (min-width: 768px) { .how-grid { grid-template-columns: 1fr 1fr; gap: 80px; } }
.how-visual {
  aspect-ratio: 4/3; background: var(--bg-card);
  border: 1px solid var(--border); border-radius: var(--radius-lg);
  position: relative; overflow: hidden;
}
.how-visual-pattern {
  position: absolute; inset: 0;
  background:
    radial-gradient(circle at 25% 35%, rgba(59,130,246,0.15), transparent 50%),
    radial-gradient(circle at 75% 65%, rgba(245,158,11,0.1), transparent 50%);
}
.how-visual-grid {
  position: absolute; inset: 0;
  background-image:
    linear-gradient(var(--border) 1px, transparent 1px),
    linear-gradient(90deg, var(--border) 1px, transparent 1px);
  background-size: 40px 40px; opacity: 0.4;
}
.how-visual-icon {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  width: 80px; height: 80px; background: var(--accent-blue);
  border-radius: var(--radius-md); display: flex;
  align-items: center; justify-content: center;
}
.how-visual-icon svg { width: 36px; height: 36px; color: #fff; }
.how-content { display: flex; flex-direction: column; gap: 20px; }
.how-headline {
  font-size: clamp(28px, 4vw, 40px); font-weight: 700;
  line-height: 1.15; letter-spacing: -0.02em;
}
.how-body { font-size: 17px; color: var(--text-secondary); line-height: 1.7; }
.how-cta {
  display: inline-flex; align-items: center; gap: 10px;
  padding: 14px 28px; border: 1px solid var(--accent-blue);
  color: var(--accent-blue); font-size: 15px; font-weight: 600;
  border-radius: var(--radius-sm); width: fit-content;
  transition: all var(--transition-fast);
}
.how-cta:hover { background: var(--accent-blue); color: #fff; }
.how-cta:focus-visible { outline: 2px solid var(--accent-blue); outline-offset: 4px; }
.how-cta svg { width: 16px; height: 16px; }

/* ========== INSIGHTS ========== */
.insights-section {
  padding: 100px 0; border-top: 1px solid var(--border);
}
@media (min-width: 768px) { .insights-section { padding: 140px 0; } }
.insights-grid {
  display: grid; grid-template-columns: 1fr; gap: 20px; margin-top: 48px;
}
@media (min-width: 640px) { .insights-grid { grid-template-columns: repeat(2, 1fr); } }
@media (min-width: 1024px) { .insights-grid { grid-template-columns: repeat(3, 1fr); } }
.insight-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
  transition: all var(--transition-base); display: flex;
  flex-direction: column;
}
.insight-card:hover { border-color: var(--border-hover); transform: translateY(-2px); }
.insight-card-image {
  width: 100%; height: 180px; object-fit: cover;
  background: linear-gradient(135deg, #1a1a2e, #16213e);
  position: relative;
}
.insight-card-type {
  position: absolute; top: 12px; left: 12px;
  font-size: 11px; font-weight: 600; text-transform: uppercase;
  letter-spacing: 0.06em; padding: 4px 10px; border-radius: 100px;
  backdrop-filter: blur(8px);
}
.insight-card-type.podcast { background: rgba(139,92,246,0.3); color: #C4B5FD; }
.insight-card-type.article { background: rgba(59,130,246,0.3); color: #93C5FD; }
.insight-card-type.report { background: rgba(245,158,11,0.3); color: #FCD34D; }
.insight-card-body { padding: 20px; flex: 1; display: flex; flex-direction: column; }
.insight-card-title {
  font-size: 16px; font-weight: 600; line-height: 1.4;
  margin-bottom: auto;
}
.insight-card-action {
  display: inline-flex; align-items: center; gap: 6px;
  margin-top: 16px; font-size: 13px; font-weight: 600;
  color: var(--accent-blue); transition: gap var(--transition-fast);
}
.insight-card-action:hover { gap: 10px; }
.insight-card-action svg { width: 14px; height: 14px; }

/* ========== PRINCIPLES ========== */
.principles-section {
  padding: 100px 0; border-top: 1px solid var(--border);
}
@media (min-width: 768px) { .principles-section { padding: 140px 0; } }
.principles-grid {
  display: grid; grid-template-columns: 1fr; gap: 24px; margin-top: 48px;
}
@media (min-width: 640px) { .principles-grid { grid-template-columns: repeat(2, 1fr); } }
.principle-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 32px;
  transition: all var(--transition-base); position: relative;
  overflow: hidden;
}
.principle-card:hover { border-color: var(--border-hover); }
.principle-card::before {
  content: ''; position: absolute; top: 0; left: 0;
  width: 3px; height: 100%; background: var(--accent-blue);
  opacity: 0; transition: opacity var(--transition-base);
}
.principle-card:hover::before { opacity: 1; }
.principle-number {
  font-size: 48px; font-weight: 800; color: rgba(255,255,255,0.04);
  line-height: 1; margin-bottom: 12px;
}
.principle-title {
  font-size: 18px; font-weight: 600; margin-bottom: 12px;
  line-height: 1.3;
}
.principle-desc {
  font-size: 14px; color: var(--text-secondary); line-height: 1.7;
}

/* ========== FOOTER ========== */
.footer {
  padding: 80px 0 0; border-top: 1px solid var(--border);
  background: var(--bg-elevated);
}
.footer-ctas {
  display: grid; grid-template-columns: 1fr; gap: 24px; margin-bottom: 64px;
}
@media (min-width: 768px) { .footer-ctas { grid-template-columns: 1fr 1fr; } }
.footer-cta-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 32px;
  transition: all var(--transition-base);
}
.footer-cta-card:hover { border-color: var(--border-hover); }
.footer-cta-text { font-size: 15px; color: var(--text-secondary); line-height: 1.6; margin-bottom: 20px; }
.footer-cta-btn {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 14px; font-weight: 600; color: var(--accent-blue);
  transition: gap var(--transition-fast);
}
.footer-cta-btn:hover { gap: 12px; }
.footer-cta-btn svg { width: 14px; height: 14px; }
.footer-bottom {
  border-top: 1px solid var(--border); padding: 32px 0;
  display: flex; flex-direction: column; gap: 24px;
}
@media (min-width: 768px) {
  .footer-bottom { flex-direction: row; justify-content: space-between; align-items: center; }
}
.footer-links { display: flex; gap: 24px; flex-wrap: wrap; }
.footer-links a {
  font-size: 13px; color: var(--text-muted);
  transition: color var(--transition-fast);
}
.footer-links a:hover { color: var(--text-secondary); }
.footer-legal { font-size: 12px; color: var(--text-muted); }

/* ========== COOKIE CONSENT ========== */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 2000;
  background: var(--bg-card); border-top: 1px solid var(--border);
  padding: 20px 24px; transform: translateY(100%);
  transition: transform var(--transition-slow);
  box-shadow: 0 -8px 32px rgba(0,0,0,0.4);
}
.cookie-banner.visible { transform: translateY(0); }
.cookie-inner {
  max-width: var(--max-width); margin: 0 auto;
  display: flex; flex-direction: column; gap: 16px;
}
@media (min-width: 768px) {
  .cookie-inner { flex-direction: row; align-items: center; gap: 24px; }
}
.cookie-text { font-size: 14px; color: var(--text-secondary); line-height: 1.6; flex: 1; }
.cookie-text a { color: var(--accent-blue); text-decoration: underline; }
.cookie-actions { display: flex; gap: 10px; flex-shrink: 0; }
.cookie-btn {
  padding: 10px 20px; border-radius: var(--radius-sm);
  font-size: 13px; font-weight: 600; transition: all var(--transition-fast);
  white-space: nowrap;
}
.cookie-btn-accept { background: var(--accent-blue); color: #fff; }
.cookie-btn-accept:hover { background: var(--accent-blue-hover); }
.cookie-btn-manage { border: 1px solid var(--border); color: var(--text-secondary); }
.cookie-btn-manage:hover { border-color: var(--border-hover); color: var(--text-primary); }
.cookie-btn-decline { border: 1px solid var(--border); color: var(--text-muted); }
.cookie-btn-decline:hover { border-color: rgba(220,38,38,0.4); color: #EF4444; }

/* Cookie Settings Modal */
.cookie-modal-overlay {
  position: fixed; inset: 0; z-index: 2001;
  background: rgba(0,0,0,0.7); backdrop-filter: blur(4px);
  opacity: 0; visibility: hidden; transition: all var(--transition-base);
}
.cookie-modal-overlay.active { opacity: 1; visibility: visible; }
.cookie-modal {
  position: fixed; top: 50%; left: 50%; z-index: 2002;
  transform: translate(-50%, -50%) scale(0.95);
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 32px;
  width: 90%; max-width: 520px; max-height: 80vh; overflow-y: auto;
  opacity: 0; visibility: hidden;
  transition: all var(--transition-base);
}
.cookie-modal.active { opacity: 1; visibility: visible; transform: translate(-50%, -50%) scale(1); }
.cookie-modal h3 { font-size: 20px; font-weight: 600; margin-bottom: 16px; }
.cookie-modal p { font-size: 14px; color: var(--text-secondary); line-height: 1.6; margin-bottom: 24px; }
.cookie-option {
  display: flex; justify-content: space-between; align-items: center;
  padding: 16px 0; border-bottom: 1px solid var(--border);
}
.cookie-option-label { font-size: 14px; font-weight: 500; }
.cookie-option-desc { font-size: 12px; color: var(--text-muted); margin-top: 4px; }
.cookie-toggle {
  width: 44px; height: 24px; border-radius: 12px;
  background: var(--text-muted); position: relative;
  transition: background var(--transition-fast); cursor: pointer;
  flex-shrink: 0;
}
.cookie-toggle.active { background: var(--accent-blue); }
.cookie-toggle::after {
  content: ''; position: absolute; top: 2px; left: 2px;
  width: 20px; height: 20px; border-radius: 50%;
  background: #fff; transition: transform var(--transition-fast);
}
.cookie-toggle.active::after { transform: translateX(20px); }
.cookie-modal-actions { display: flex; gap: 10px; margin-top: 24px; justify-content: flex-end; }

/* ========== REDUCED MOTION ========== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  html { scroll-behavior: auto; }
}

/* ========== SCROLLBAR ========== */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.2); }
</style>
