python3 -c "
from html.parser import HTMLParser
import sys

class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.void_elements = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
        self.errors = []

    def handle_starttag(self, tag, attrs):
        if tag not in self.void_elements:
            self.stack.append((tag, self.getpos()))

    def handle_endtag(self, tag):
        if tag in self.void_elements:
            return
        if not self.stack:
            self.errors.append(f'Unexpected closing tag </{tag}> at {self.getpos()}')
            return
        expected_tag, pos = self.stack.pop()
        if expected_tag != tag:
            self.errors.append(f'Mismatched: expected </{expected_tag}> (opened at {pos}) but got </{tag}> at {self.getpos()}')

with open('/app/output/index.html', 'r') as f:
    content = f.read()

v = Validator()
v.feed(content)

if v.errors:
    for e in v.errors[:10]:
        print(f'ERROR: {e}')
elif v.stack:
    for tag, pos in v.stack[:5]:
        print(f'UNCLOSED: <{tag}> at {pos}')
else:
    print('HTML structure is valid')
"

